const b = ($json && $json.body) ? $json.body : ($json || {});

const content = String(b.content || '').trim();
const parts = content.split(/\s+/).filter(Boolean);

let cmd = (parts[0] || '').toLowerCase();

if (cmd.charAt(0) === '!') {
  cmd = cmd.slice(1);
}

const rest = parts.slice(1).join(' ').trim();

const known = [
  'watch',
  'unwatch',
  'watchlist',
  'price',
  'game',
  'deal',
  'alerts',
  'clearwatchlist',
  'help'
];

let confirm = false;
let game = rest;

if (cmd === 'clearwatchlist') {
  confirm = rest.toLowerCase() === 'confirm';
  game = '';
}

const command = known.indexOf(cmd) >= 0 ? cmd : 'help';

const userId = String(
  b.user_id ||
  (b.author && b.author.id) ||
  ''
);

const username = String(
  b.username ||
  (b.author && b.author.username) ||
  ''
);

// The channel_id from the incoming Discord message.
// If the message is inside a Forum thread, this may be
// the thread/channel ID rather than the parent forum ID.
const channelId = String(
  b.channel_id ||
  (b.channel && b.channel.id) ||
  ''
);

// Parent Forum Channel ID, if your webhook/API provides it.
const forumId = String(
  b.forum_id ||
  b.parent_channel_id ||
  b.parent_id ||
  (b.channel && b.channel.parent_id) ||
  ''
);

// Thread ID, if the message came from a Discord Forum thread.
const threadId = String(
  b.thread_id ||
  (b.thread && b.thread.id) ||
  ''
);

const messageId = String(
  b.message_id ||
  b.id ||
  ''
);

const guildId = String(
  b.guild_id ||
  (b.guild && b.guild.id) ||
  ''
);

return [
  {
    json: {
      // Command information
      command: command,
      game_name: game,
      confirm: confirm,

      // User information
      user_id: userId,
      username: username,

      // Discord destination
      channel_id: channelId,
      forum_id: forumId,
      thread_id: threadId,

      // Discord message information
      message_id: messageId,

      // Discord server
      guild_id: guildId
    }
  }
];

const ctx = $json;
const LF = String.fromCharCode(10);
const lines = ['\uD83C\uDFAE GAME WATCHLIST BOT \u2014 COMMANDS', '',
  '!watch <game>        add a game to your watchlist',
  '!unwatch <game>      remove a game from your watchlist',
  '!watchlist           show your tracked games',
  '!price <game>        current price now',
  '!game <game>         detailed game info',
  '!deal <game>         best current deals',
  '!alerts              your recent alerts',
  '!clearwatchlist      clear your watchlist',
  '!help                show this message'];
return {
  reply_message: lines.join(LF),
  reply_channel_id: ctx.channel_id,
  reply_guild_id: ctx.guild_id,
  reply_forum_id: ctx.forum_id,
  reply_thread_id: ctx.thread_id,
  reply_message_id: ctx.message_id
};

let results = [];
try { results = JSON.parse($json.data); } catch (e) { results = []; }
if (!Array.isArray(results)) results = [];
const ctx = $('Parse Discord Command').item.json;
const wanted = String(ctx.game_name || '').toLowerCase();
let best = results.find((r) => String(r.title || '').toLowerCase() === wanted) || results[0] || null;
return {
  command: ctx.command,
  user_id: ctx.user_id,
  username: ctx.username,
  channel_id: ctx.channel_id,
  guild_id: ctx.guild_id,
  forum_id: ctx.forum_id,
  thread_id: ctx.thread_id,
  message_id: ctx.message_id,
  game_id: best ? best.id : '',
  game_name: best ? best.title : ctx.game_name,
  requested_name: ctx.game_name,
};

const ctx = $('Extract Best Game Match').item.json;
const cmd = ctx.command;
let pr = []; let low = [];
try { pr = JSON.parse($('Fetch Prices From ITAD').item.json.data || '[]'); } catch (e) { pr = []; }
try { low = JSON.parse($('Fetch ITAD Historical Low').item.json.data || '[]'); } catch (e) { low = []; }
const gid = ctx.game_id;
const priceEntry = Array.isArray(pr) ? (pr.find((x) => x.id === gid) || pr[0]) : null;
const lowEntry = Array.isArray(low) ? (low.find((x) => x.id === gid) || low[0]) : null;
const itadLow = lowEntry && lowEntry.low ? Number(lowEntry.low.amount) : null;
const deals = (priceEntry && priceEntry.deals) || [];
const sorted = deals.slice().filter((d) => d && d.price).sort((a, b) => Number(a.price.amount) - Number(b.price.amount));
const best = sorted[0] || null;
const cur = best && best.price ? Number(best.price.amount) : null;
const cut = best && best.cut != null ? Number(best.cut) : 0;
const store = best && best.shop ? best.shop.name : '';
const url = best ? (best.url || '') : '';
const cy = best && best.price ? best.price.currency : 'INR';
const LF = String.fromCharCode(10);
const fmt = (n) => (n == null ? 'N/A' : '\u20B9' + Number(n).toLocaleString('en-IN'));
let msg = ''; let save = false;
if (cmd === 'watch') {
  save = true;
  const lines = ['\uD83C\uDFAE Added to your watchlist!', '', ctx.game_name, '', '\uD83D\uDCB0 Current price: ' + fmt(cur), '\uD83C\uDFF7\uFE0F Discount: ' + cut + '%', '\uD83D\uDCC9 Historical low: ' + fmt(itadLow), '', "I'll check this game automatically every 6 hours.", '', "You'll be notified when:", '\u2022 the price drops significantly', '\u2022 the game reaches a new historical low', '\u2022 the game becomes free', '\u2022 a major deal appears'];
  msg = lines.join(LF);
} else if (cmd === 'price') {
  const lines = ['\uD83C\uDFAE ' + ctx.game_name, '', '\uD83D\uDCB0 Current: ' + fmt(cur), '\uD83C\uDFF7\uFE0F Discount: ' + cut + '%', '\uD83D\uDCC9 Historical Low: ' + fmt(itadLow), '', '\uD83C\uDFEA Best Store:', store || 'N/A', '', '\uD83D\uDD17 Store Link:', url || 'N/A', '', 'Last checked: just now'];
  msg = lines.join(LF);
} else if (cmd === 'game') {
  const lines = ['\uD83C\uDFAE ' + String(ctx.game_name).toUpperCase(), '', 'Current Price:', fmt(cur), '', 'Discount:', cut + '%', '', 'Historical Low:', fmt(itadLow), '', 'Best Current Deal:', (store ? store + ' - ' : '') + fmt(cur), '', 'Use:', '!watch ' + ctx.game_name, '', 'to add it to your watchlist.'];
  msg = lines.join(LF);
} else if (cmd === 'deal') {
  const lines = ['\uD83D\uDD25 BEST DEALS \u2014 ' + String(ctx.game_name).toUpperCase(), ''];
  const top = sorted.slice(0, 5);
  if (!top.length) { lines.push('No current deals found.'); }
  top.forEach((d, i) => { lines.push((i + 1) + '. ' + (d.shop ? d.shop.name : 'Store')); lines.push('   ' + fmt(Number(d.price.amount))); lines.push('   -' + (d.cut != null ? Number(d.cut) : 0) + '%'); lines.push(''); });
  lines.push('\uD83D\uDCC9 Historical Low: ' + fmt(itadLow));
  msg = lines.join(LF);
}
return {
  reply_message: msg,
  reply_channel_id: ctx.channel_id,
  reply_guild_id: ctx.guild_id,
  reply_forum_id: ctx.forum_id,
  reply_thread_id: ctx.thread_id,
  reply_message_id: ctx.message_id,
  save: save,
  user_id: ctx.user_id,
  username: ctx.username,
  guild_id: ctx.guild_id,
  channel_id: ctx.channel_id,
  game_name: ctx.game_name,
  itad_game_id: gid,
  game_url: url,
  platform: '',
  currency: cy,
  last_price: cur,
  last_discount: cut,
};

const ctx = $('Parse Discord Command').item.json;
const LF = String.fromCharCode(10);
const msg = ['\u2753 No matching game found for:', '', ctx.game_name, '', 'Please check the spelling and try again.'].join(LF);
return { reply_message: msg, reply_channel_id: ctx.channel_id, reply_guild_id: ctx.guild_id, reply_forum_id: ctx.forum_id, reply_thread_id: ctx.thread_id, reply_message_id: ctx.message_id };

const ctx = $('Parse Discord Command').first().json;
const LF = String.fromCharCode(10);
const msg = ['\uD83D\uDDD1\uFE0F Removed from your watchlist:', '', ctx.game_name, '', "I won't track this game anymore."].join(LF);
return [{ json: { reply_message: msg, reply_channel_id: ctx.channel_id, reply_guild_id: ctx.guild_id, reply_forum_id: ctx.forum_id, reply_thread_id: ctx.thread_id, reply_message_id: ctx.message_id } }];

const rows = $input.all().map((i) => i.json).filter((r) => r && Object.keys(r).length && r.game_name);
const ctx = $('Parse Discord Command').first().json;
const LF = String.fromCharCode(10);
const fmt = (n) => (n == null || n === '' ? 'N/A' : '\u20B9' + Number(n).toLocaleString('en-IN'));
let msg;
if (!rows.length) {
  msg = ['\uD83C\uDFAE Your watchlist is empty.', '', 'Use:', '!watch <game>', '', 'Example:', '!watch Cyberpunk 2077'].join(LF);
} else {
  const lines = ['\uD83C\uDFAE YOUR GAME WATCHLIST', ''];
  rows.forEach((r, i) => {
    lines.push((i + 1) + '. ' + r.game_name);
    lines.push('   \uD83D\uDCB0 ' + fmt(r.last_price) + ' | -' + (r.last_discount || 0) + '%');
    lines.push('');
  });
  lines.push('\u23F1\uFE0F Prices are checked every 6 hours.');
  msg = lines.join(LF);
}
return [{ json: { reply_message: msg, reply_channel_id: ctx.channel_id, reply_guild_id: ctx.guild_id, reply_forum_id: ctx.forum_id, reply_thread_id: ctx.thread_id, reply_message_id: ctx.message_id } }];

const rows = $input.all().map((i) => i.json).filter((r) => r && Object.keys(r).length && r.game_name);
const ctx = $('Parse Discord Command').first().json;
const LF = String.fromCharCode(10);
const fmt = (n) => (n == null || n === '' ? 'N/A' : '\u20B9' + Number(n).toLocaleString('en-IN'));
let msg;
if (!rows.length) {
  msg = ['\uD83D\uDD14 You have no recent alerts yet.'].join(LF);
} else {
  const lines = ['\uD83D\uDD14 YOUR RECENT GAME ALERTS', ''];
  rows.slice(0, 10).forEach((r) => {
    lines.push(r.game_name);
    if (r.alert_type === 'free') lines.push('\uD83C\uDD93 Free');
    else if (r.alert_type === 'historical_low') lines.push('New historical low ' + fmt(r.alert_price));
    else if (r.alert_type === 'target') lines.push('\uD83C\uDFAF Target price reached ' + fmt(r.alert_price));
    else lines.push(fmt(r.alert_price) + ' (' + (r.alert_type || 'alert') + ')');
    lines.push('');
  });
  msg = lines.join(LF);
}
return [{ json: { reply_message: msg, reply_channel_id: ctx.channel_id, reply_guild_id: ctx.guild_id, reply_forum_id: ctx.forum_id, reply_thread_id: ctx.thread_id, reply_message_id: ctx.message_id } }];

const ctx = $('Parse Discord Command').first().json;
const LF = String.fromCharCode(10);
const msg = ['\u2705 Your watchlist has been cleared.', '', 'All games have been removed.'].join(LF);
return { reply_message: msg, reply_channel_id: ctx.channel_id, reply_guild_id: ctx.guild_id, reply_forum_id: ctx.forum_id, reply_thread_id: ctx.thread_id, reply_message_id: ctx.message_id };

const ctx = $json;
const LF = String.fromCharCode(10);
const msg = ['\u26A0\uFE0F This will remove all games from your watchlist.', '', 'Reply:', '!clearwatchlist confirm'].join(LF);
return { reply_message: msg, reply_channel_id: ctx.channel_id, reply_guild_id: ctx.guild_id };

const rows = $input.all().map((i) => i.json).filter((r) => r && Object.keys(r).length && r.itad_game_id);
const ids = [];
const seen = {};
rows.forEach((r) => { if (!seen[r.itad_game_id]) { seen[r.itad_game_id] = true; ids.push(r.itad_game_id); } });
return [{ json: { ids: ids } }];

const cur = $('Normalize Price Data').all().map((i) => i.json);
const curByGame = {};
cur.forEach((c) => { curByGame[c.game_id] = c; });
const hist = $('Load Price History').all().map((i) => i.json).filter((r) => r && Object.keys(r).length);
const histMap = {};
hist.forEach((h) => { histMap[h.game_id + '|' + h.store] = h; });
const sent = $('Load Sent Alerts').all().map((i) => i.json).filter((r) => r && Object.keys(r).length);
const sentKeys = {};
sent.forEach((s) => { sentKeys[s.dedup_key] = true; });
const wl = $('Retrieve Active Watchlist').all().map((i) => i.json).filter((r) => r && Object.keys(r).length && r.is_active !== false);
const now = new Date().toISOString();
const LF = String.fromCharCode(10);
const fmt = (n) => (n == null ? 'N/A' : '\u20B9' + Number(n).toLocaleString('en-IN'));
const out = [];
wl.forEach((entry) => {
  const c = curByGame[entry.itad_game_id];
  if (!c) return;
  const cp = Number(c.current_price);
  const prev = histMap[c.game_id + '|' + c.store];
  const prevPrice = prev ? Number(prev.current_price) : null;
  const prevLow = prev ? Number(prev.historical_low) : null;
  const itadLow = c.itad_history_low != null ? Number(c.itad_history_low) : null;
  const lowCand = [cp];
  if (prevLow != null && !isNaN(prevLow)) lowCand.push(prevLow);
  if (itadLow != null && !isNaN(itadLow)) lowCand.push(itadLow);
  const historical_low = Math.min.apply(null, lowCand.filter((x) => !isNaN(x)));
  const disc = Number(c.discount_percent) || 0;
  const target = entry.target_price != null && Number(entry.target_price) > 0 ? Number(entry.target_price) : null;
  const pctDrop = prevPrice && prevPrice > 0 ? Math.round(((prevPrice - cp) / prevPrice) * 10000) / 100 : 0;
  let type = ''; let title = '';
  if (cp === 0 && entry.alert_on_free !== false) { type = 'free'; title = '\uD83C\uDD93 FREE GAME ALERT!'; }
  else if (target != null && cp <= target) { type = 'target'; title = '\uD83C\uDFAF TARGET PRICE REACHED!'; }
  else if (cp <= historical_low && entry.alert_on_historical_low !== false) { type = 'historical_low'; title = '\uD83D\uDCC9 NEW HISTORICAL LOW!'; }
  else if (prevPrice != null && cp < prevPrice && pctDrop >= 10 && entry.alert_on_price_drop !== false) { type = 'price_drop'; title = '\uD83D\uDD25 PRICE DROP!'; }
  else if (disc >= 70 && entry.alert_on_discount !== false) { type = 'big_discount'; title = '\uD83C\uDFF7\uFE0F HUGE DISCOUNT!'; }
  const dedup_key = entry.user_id + '|' + c.game_id + '|' + type + '|' + cp;
  const should_alert = !!type && !sentKeys[dedup_key];
  let msg = '';
  if (type === 'target') {
    msg = [title, '', c.game_name, '', 'Current price: ' + fmt(cp), 'Your target: ' + fmt(target), 'Discount: ' + disc + '%', '', 'This game has reached your target price.'].join(LF);
  } else if (type) {
    const lines = [title, '', c.game_name, ''];
    if (prevPrice != null) lines.push(fmt(prevPrice) + ' \u2192 ' + fmt(cp)); else lines.push('Current: ' + fmt(cp));
    if (pctDrop > 0) lines.push('\uD83D\uDCC9 ' + pctDrop + '% price drop');
    lines.push('\uD83C\uDFF7\uFE0F Discount: ' + disc + '%');
    lines.push('\u2B50 Historical low: ' + fmt(historical_low));
    lines.push('');
    lines.push('This game is on your watchlist.');
    if (c.store_url) { lines.push(''); lines.push('\uD83D\uDD17 ' + c.store_url); }
    msg = lines.join(LF);
  }
  out.push({ json: {
    user_id: entry.user_id,
    game_id: c.game_id,
    game_name: c.game_name,
    store: c.store,
    current_price: cp,
    discount_percent: disc,
    historical_low: historical_low,
    currency: c.currency,
    store_url: c.store_url,
    reply_channel_id: entry.channel_id,
 reply_forum_id: entry.forum_id,
 reply_guild_id: entry.guild_id,
    entry_game_id: entry.itad_game_id,
    alert_type: type,
    dedup_key: dedup_key,
    alert_price: cp,
    should_alert: should_alert,
    reply_message: msg,
    checked_at: now,
  } });
});
return out;
